1	// pm/brain.js — 项目管理的判断脑（H49）：fable 档，事件唤醒，只出建议不落裁决
2	// v0.18-alpha 职能：切单（拍板父单 → 单元子单草稿 + 拆单简报呈 Claude 审批）。
3	// 硬边界：产出全为草稿与简报——放行/裁决权不在此模块（人本化）。
4	const fs = require('fs');
5	const path = require('path');
6	const os = require('os');
7	const { spawn } = require('child_process');
8	const store = require('../core/store');
9	const ledger = require('./ledger');
10	
11	// 管理费记账（H49 报表单列，0.22.3 补接线）：从事件流提取真实用量入台账
12	function extractUsage(raw) {
13	  // 输入/缓存分列（2026-08-05）：缓存读计费约为常价 1/10，混进合计会虚胖离群（起草 57.9 万 token 案）
14	  let inTok = 0, cacheTok = 0, outTok = 0;
15	  for (const line of String(raw).split(String.fromCharCode(10))) {
16	    const s = line.replace(String.fromCharCode(13), '').trim();
17	    if (!s.startsWith('{')) continue;
18	    try { const e = JSON.parse(s);
19	      const u = (e.usage) || (e.message && e.message.usage);
20	      if (u) {
21	        if (u.input_tokens) inTok = Math.max(inTok, u.input_tokens);
22	        if (u.cache_read_input_tokens) cacheTok = Math.max(cacheTok, u.cache_read_input_tokens);
23	        if (u.output_tokens) outTok += u.output_tokens;
24	      }
25	    } catch { /* 忽略 */ }
26	  }
27	  return { input: inTok, cache: cacheTok, output: outTok };
28	}
29	function billFee(root, 用途, raw) {
30	  try { const u = extractUsage(raw);
31	    ledger.update(root, (l) => { l.管理费 = l.管理费 || { token合计: 0, 次数: 0 };
32	      l.管理费.token合计 += u.input + u.output; l.管理费.次数 += 1;
33	      l.管理费.缓存合计 = (l.管理费.缓存合计 || 0) + u.cache;
34	      l.管理费.明细 = l.管理费.明细 || []; l.管理费.明细.push({ t: new Date().toISOString(), 用途, 输入: u.input, 缓存: u.cache, 输出: u.output, tokens: u.input + u.output });
35	      if (l.管理费.明细.length > 200) l.管理费.明细 = l.管理费.明细.slice(-200);
36	    });
37	  } catch { /* 记账失败不阻塞 */ }
38	}
39	
40	// 作业态（0.23.7 呼吸灯）：项管 LLM 会话起止登记，供信道在线灯显示
41	let working = null;
42	function setWorking(w) { working = w ? { ...w, 起时: new Date().toISOString() } : null; }
43	function getWorking() { return working; }
44	
45	function cli() {
46	  const home = os.homedir();
47	  const cands = [path.join(home, '.local', 'bin', 'claude.exe'), path.join(home, 'AppData', 'Roaming', 'npm', 'claude.cmd'), 'claude'];
48	  return cands.find((c) => c === 'claude' || fs.existsSync(c));
49	}
