51	// 切单提示词：六件套纪律 + 单型库 + 单元标准 + 机器可读输出契约
52	function buildCutPrompt(root, cfg, parent, projPath) {
53	  const read = (f) => { try { return fs.readFileSync(path.join(root, f), 'utf8'); } catch { return ''; } };
54	  const 单元 = (cfg.单元 || {});
55	  return [
56	    '你是单流的「项目管理」职能（fable 档）。任务：把下面的拍板父单切成单元子单草稿。',
57	    '宪法要句（H80，规则空白时按此裁并注明依据）：①自动化——能给机器的不耗人 ②模块化——换实现不换协议 ③透明化——一切留痕如实呈报 ④自优化——教训必须变成协议或工具的改动 ⑤人本化——品味/取舍/方向/销毁性决定只属于人，AI 仅建议与执行。',
58	    `项目仓库（可读，用于仓况盘点）：${projPath || '（未注册）'}`,
59	    '',
60	    '=== 拆单六件套（缺一不拆，按序执行）===',
61	    '①仓况盘点：先扫项目仓相关目录，列出已有实现，绝不重复造轮',
62	    '②调研先行判断：未知数多则第一张子单必须是调研单',
63	    '③历史校准：预计时间用 agent 实测口径（' + (单元.小时 || 0.25) + 'h/单元，≤' + (单元.token || 50000) + ' token）',
64	    '④协议选段：把相关纪律写进各子单「不要做」与验收标准',
65	    '⑤依赖建模：同写区串行（依赖链）、异写区并行；标注红链',
66	    '⑥单元合规自检：每张 ≤2 单元、单一写区、验收标准全部可判定（GWT/勾选）',
67	    '⑧验收锚点归位（TK-78/75 两案）：受控重建、SavedScene 在位断言、场景体积闸这类收尾锚点，只准写进最后一张装配单的验收标准——写进前置单必与其「不要做」互斥，烧判官轮次',
68	    '⑦结构归位（H50/H51）：工单树是项管资产，管线是顶层单位——若本父单无管线章（frontmatter 管线: P-#），在简报里提出应挂入的既有管线，或建议开新线（开线是制作人人闸，你只有建议权）；判不出写「呈制作人定归属」',
69	    '⑩短题制（H83，2026-08-06 制作人裁决，适用全部单型——子单/专项/父单/机制单一视同仁）：标题 ≤16 字、「对象+动作」结构（如「海岸线钉零与衰减」），不堆机制词不带括号补语；范围枚举（①②③…）一律写进正文「范围」章，禁入标题——标题是卡片的脸，长到要点进详情才认得出就是不合格（制作人反馈拆名太乱）',
70	    '⑪用工语境（H85 + 同日「去岗位化」补章，2026-08-06 制作人裁决）：编制数据与调整权在你（项管）手上——监制台参数页已无编制管理区，改编制走 /api/pm/roster（GET 取快照，POST 体 {改动:[{职能,池序:[{池,档}]}],理由}）。**编制表每职能一行，没有 程序-A/程序-B 这类岗位号**：派发制下执行者因单而生，同一编制想开几个无头 CLI 就开几个，所以编制记的是「这个职能能在哪些池上干、按什么优先级」——池序第一位是首选池，档为空即用池默认模型。池路由按池序与额度实况定：池序里还有未冻结的池就顺位取用（不算改挂）；整条池序全冻时派发引擎才临时借调到可用池（自动动作只此一种，会留 fm.临时改池 + 台账）；其余用工调整由你显式发起，别指望自动。',
71	    '⑫并发调配语境（施工令-010，2026-08-06 制作人批准）：并发调配权随编制权同规格归你——审检并发（两检初检/核查/仲裁 各自的判官槽数，默认 1）与各池并发上限都由你按积压动态调，走 /api/pm/concurrency（GET 取聚合快照，POST 体 {审检?,零输出分钟?,池?:{codex,claude,deepseek},理由}）。审检并行不是默认（制作人已否决写死并行）：待验收/待定夺真堆起来了才调，堆完了调回去。硬顶是成本保险丝、只有制作人能改，越顶一律 400 拒绝——别试。',
72	    '⑨分级检审（2026-08-05 制作人批准）：QA 字段按单型定死——代码/装配/程序类=开（全检）；文档/wiki/调研/工程类=关（简检，仅核查两检）；验收方式=保留 的品味单免检直达制作人。不逐单裁量。',
73	    '',
74	    '=== 单型库（只从六型选：调研单/方案单/实现单/装配单/修复单/工程单）===',
75	    '工程单（H71）：纯机械体力活——批量替换/清洗/格式化/迁移，零设计判断零技术抉择；frontmatter 必须盖 执行池: deepseek（最便宜池），QA: 关（简检口径）。验收标准必须全机判（grep 计数/文件清单比对）。',
76	    '调研单（H90）：未知数排查的先行单——调研结论文档本身就是交付物。**产物路径口径（施工令-020）：调研结论一律落 `Docs/SLG/调研方案/<题目>.md`**（竞品横评落 `Docs/SLG/竞品分析/`），两者同挂监制台 wiki「调研方案」分区；产出物路径写别处即返修。执行会话必须调异厂评审台（packages/review-panel/review.js，喂调研结论 md 全绝对路径）过一遍全员评审，命令口径同方案单：评审团自动发现、异厂全到，少一席要写缺席原因；额度耗尽则弃对应厂并在回执如实记录。回执必带附录三件：①各厂意见原文 ②逐条采纳/驳回（驳回写理由）③由此产生的修订点。评审台已行**红队立场卷制**（H91/施工令-019）：三卷（可行性红队/不变量红队/成本红队）按席序轮换派发、单厂在席时独领全部三卷，每卷必须尝试构造具体失败场景，构造不出要明写「未能构造击杀」——该声明本身即通过证据。验收标准必须含评审台证据项（意见合集 md 绝对路径 + 附录三件齐备 + 击杀结论：各厂领卷与击杀/未杀条数，缺席致落空的立场卷如实标注）。质检阶段按 H93 只做击杀点定向复核，零击杀免次轮。',
77	    '方案单（H88）：承重技术方案的设计单——先出方案再动手，方案本身就是交付物。frontmatter 定死：职能: 技术策划、产出物类型: 文档、QA: 开、验收方式: 委托（承重设计不吃⑨「文档类=关」的简检口径，这是明定例外）。正文按五章契约写（章名以协议库 H88 正本为准，至少覆盖 问题与目标／不变量／路径划分与取舍／验证法／实现风险与回滚），缺章即返修。执行会话必须调异厂评审台（packages/review-panel/review.js，喂方案 md 全绝对路径）过一遍全员评审——评审团自动发现、异厂全到，少一席要写缺席原因。回执必带附录三件：①各厂意见原文 ②逐条采纳/驳回（驳回写理由）③由此产生的修订点。质检阶段定向复核（H90，经 H93 收窄 2026-08-09）——执行阶段全量异厂对抗性评审为唯一全量轮；QA 质检只对首轮击杀点+对应修订处定向对抗复核（回执击杀点清单即次轮卷面），零击杀免次轮；额度耗尽则弃对应厂并如实记录。评审台已行**红队立场卷制**（H91/施工令-019）：三卷（可行性红队/不变量红队/成本红队）按席序轮换派发、单厂在席时独领全部三卷，每卷必须尝试构造具体失败场景，构造不出要明写「未能构造击杀」——该声明本身即通过证据。验收标准必须含评审台证据项（意见合集 md 绝对路径 + 附录三件齐备 + 击杀结论：各厂领卷与击杀/未杀条数，缺席致落空的立场卷如实标注）。',
78	    '承重实现单挂依据（H88）：凡实现单落在已出方案的承重面上，frontmatter 必须写 依据: <已落袋的方案单号>——方案没落袋就不许切实现单，先切方案单、再把实现单的 依赖 挂到它身上。',
79	    '实现单/装配单/修复单——无方案不开工（H92 项管侧，施工令-020）：程序与装配类单型的**依据栏应指向已落袋技术方案**（方案单号或 `Docs/SLG/技术方案/` 下已定案的那一篇）；**无对应方案先切方案单**，再把本单 依赖 挂上去。判不出该挂哪篇就是方案缺位，按缺位处置——不许拿「边做边定」搪塞。',
80	    '职能定夺（H98）：职能按改动面实质定——改动面全落 Scripts/Tests 代码的单一律 职能: 程序（不论单型叫什么）；装配单型只用于场景/预制体/资产拼装写区动作。',
81	    '管线归属必填：凡属某条管线域的单（看板管线注册表见 /api/pipelines 或工单正文域语义），frontmatter 必须写 管线: P-N；确无归属的独立杂务才允许留空进散单。案源：TK-106~116 整条地图施工链漏章堆散单，制作人亲自抓出。',
82	    '不设收口单（H56）：全部子单完成后项管自动生成收口报告、专项父单自动转待验收——制作人的保留签字在父单，一个专项只签一次（H53）。最后一张实现/装配单须含受控重建与全量测试绿的交付责任。',
83	    '',
84	    '=== 输出契约（机器解析，严格遵守）===',
85	    '每张子单一个代码块，格式：',
86	    '```ticket',
87	    'title: <标题>',
88	    '单型: <调研单|方案单|实现单|装配单|修复单|工程单>',
89	    '职能: <策划|技术策划|程序|美术|QA|装配>',
90	    '产出物类型: <代码|文档|资产|规格|场景>',
91	    '优先级: <P0|P1|P2>',
92	    'QA: <开|关>',
93	    '验收方式: <委托|保留>',
94	    '预计时间: <小时数>',
95	    '预计token: <数字>',
96	    '依赖: <逗号分隔的同批序号如 1,2；无则留空>',
97	    '依据: <承重实现单填已落袋的方案单号（H88）；其余留空>',
98	    '管线: <本单所属管线号 P-N（注册表见 /api/pipelines）；确无归属的独立杂务才留空>',
99	    '---',
100	    '<正文：## 范围 / ## 不要做 / ## 验收标准>',
101	    '```',
102	    '全部子单之后，输出「## 拆单简报」：切法理由、依赖图、红链、预计总耗时与总 token。',
103	    '',
104	    '=== 拍板父单 ===',
105	    parent.body || '',
106	    '',
107	    '（父单 frontmatter：项目=' + (parent.fm.项目 || '') + '，编号=' + parent.id + '）',
108	  ].join('\n');
109	}
110	
111	// 解析输出契约 → 子单数组
112	function parseTickets(text) {
113	  const out = [];
114	  const re = /```ticket\n([\s\S]*?)```/g;
115	  let m;
116	  while ((m = re.exec(text))) {
117	    const [head, ...bodyParts] = m[1].split(/^---$/m);
118	    const fm = {};
119	    for (const line of head.split('\n')) {
120	      const mm = line.match(/^([\w一-鿿]+):\s*(.*)$/);
121	      if (mm) fm[mm[1]] = mm[2].trim();
122	    }
123	    out.push({ fm, body: bodyParts.join('---').trim() });
124	  }
125	  const brief = (text.match(/## 拆单简报[\s\S]*$/) || [''])[0].trim();
126	  return { tickets: out, brief };
127	}
128	
129	// 子单 frontmatter 白名单：ticket 块解析出来的字段，只有列在这里的才落得到盘。
130	// 抽成纯函数是为了能单测——白名单漏字段已经吃过两次（H88 依据、TK-106~116 管线），
131	// 都是「提示词要求写了、落盘时被静默吞掉」，肉眼审不出来。
132	// ids 用于把 依赖 里的同批序号（1,2…）换成实际编号。
133	function childFm(tk, { id, ids, parentId, 项目 }) {
134	  const dep = String(tk.fm.依赖 || '').split(/[，,\s]+/).filter(Boolean)
135	    .map((n) => (ids || [])[Number(n) - 1]).filter(Boolean).join('，');
136	  return {
137	    id, title: tk.fm.title || '子单', 职能: tk.fm.职能 || '程序',
138	    产出物类型: tk.fm.产出物类型 || '代码', 优先级: tk.fm.优先级 || 'P1', 规模: '单兵',
139	    QA: tk.fm.QA || '开', 验收方式: tk.fm.验收方式 || '委托',
140	    预计时间: tk.fm.预计时间 || '0.25', 预计token: tk.fm.预计token || '50000',
141	    项目, 创建时间: new Date().toISOString().slice(0, 10),
142	    父单: parentId, ...(dep ? { 依赖: dep } : {}),
143	    ...(tk.fm.依据 ? { 依据: tk.fm.依据 } : {}), // H88：承重实现单挂方案单号，白名单不带就落不到盘
144	    ...(tk.fm.管线 ? { 管线: tk.fm.管线 } : {}), // TK-106~116：管线归属同理，不带就只能靠父链继承
145	    单型: tk.fm.单型 || '实现单', 切单人: '项管',
146	  };
147	}
148	
149	// 单张起草单的 frontmatter 白名单（draftTicket 用，与 childFm 同口径、独立一份因为无父单/无同批依赖）。
150	// 无父单意味着归属没得继承——管线漏写就直接进散单行（TK-115/116 案发现场），比子单路径更该带。
151	function draftFm(tk, { id, 项目, 粒ID }) {
152	  return {
153	    id, title: tk.fm.title || '起草单', 职能: tk.fm.职能 || '程序', 产出物类型: tk.fm.产出物类型 || '代码',
154	    优先级: tk.fm.优先级 || 'P1', 规模: '单兵', QA: tk.fm.QA || '开', 验收方式: tk.fm.验收方式 || '委托',
155	    预计时间: tk.fm.预计时间 || '0.25', 预计token: tk.fm.预计token || '50000', 项目,
156	    单型: tk.fm.单型 || '修复单', 切单人: '项管', 创建时间: new Date().toISOString().slice(0, 10),
157	    ...(tk.fm.依据 ? { 依据: tk.fm.依据 } : {}), // H88：同 cut，依据栏要落盘
158	    ...(tk.fm.管线 ? { 管线: tk.fm.管线 } : {}), // TK-106~116：同 cut，管线归属要落盘
159	    // 施工令-040：粒ID 由委托方（/api/pm/draft 请求体）指定，不由起草模型自填——
160	    // 它是台账与工单池的对账钥匙，让模型猜一个等于让账目自己长出来。
161	    ...(粒ID ? { 粒ID: String(粒ID) } : {}),
162	  };
163	}
164	
165	// 切单主流程：调 fable → 解析 → 建草稿挂父单 → 简报落台账待审
166	function cut(root, cfg, parentId, projPath, cb) {
167	  const parent = store.find(root, parentId);
168	  if (!parent) return cb({ ok: false, error: '父单不存在' });
