    编辑器锁: (() => { try { return require('./core/state').read(root).编辑器锁 || {}; } catch { return {}; } })(),
    引擎作业: engineJobs(cfg), // 项目名 → 引擎作业状态（无锁的项目不出键）
    上轮: lastTick,
