}

// 各注册项目的引擎作业（H83 后续 · TK-97 案）：读锁与测试日志心跳，任何缺失静默跳过。
function engineJobs(cfg) {
  const out = {};
  try {
    const engines = require('./engines');
    const reg = (cfg && cfg.项目 && cfg.项目.注册) || {};
    for (const [name, r] of Object.entries(reg)) {
