// exe 重启即清空，tick 为"在途/质检有主办但无执行记录"的单重新拉起（断点恢复）。
const running = new Map();
let loopTimer = null;
let lastTick = null;

const busyTickets = () => new Set([...running.values()].map((e) => e.id));
